import React from 'react';

const Footer = () => {
  return (
    <footer
      style={{
        marginTop: 'auto',
        backgroundColor: '#ffffff',
        borderTop: '1px solid var(--border)',
        padding: '1.5rem 0',
        color: 'var(--text-muted)',
        fontSize: '0.85rem',
        textAlign: 'center',
      }}
    >
      <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '0 1.5rem' }}>
        <p>© {new Date().getFullYear()} School Notice Board Management System. All rights reserved.</p>
        <p style={{ marginTop: '0.35rem', fontSize: '0.75rem', color: 'var(--text-light)' }}>
          Powered by Spring Boot 3 & React • Role-Based Access Control • Live Analytics
        </p>
      </div>
    </footer>
  );
};

export default Footer;
